  rdfs:range :Organization .
:assignedOrganization a owl:FunctionalProperty .
:organizationAssignedTo a owl:ObjectProperty ;
  rdfs:label "organization assigned to" ;
  rdfs:comment "Inverse of assignedOrganization." ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  owl:inverseOf :assignedOrganization .
:assignedAddress a owl:ObjectProperty ;
  rdfs:label "assigned address" ;
  rdfs:comment "Links a role assignment to an address." ;
