  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceAmount .
:hasInvoiceAmount a owl:FunctionalProperty .
:invoiceAmountOf a owl:ObjectProperty ;
  rdfs:label "invoice amount of" ;
  rdfs:comment "Inverse of hasInvoiceAmount." ;
  rdfs:domain :InvoiceAmount ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasInvoiceAmount .
:hasTax a owl:ObjectProperty ;
  rdfs:label "has tax" ;
  rdfs:comment "Links a summary section to tax breakdowns." ;
  rdfs:domain :SummarySection ;
  rdfs:range :Tax .
:taxOf a owl:ObjectProperty ;
  rdfs:label "tax of" ;
  rdfs:comment "Inverse of hasTax." ;
  rdfs:domain :Tax ;
  rdfs:range :SummarySection ;
  owl:inverseOf :hasTax .
:hasBusinessProcess a owl:ObjectProperty ;
  rdfs:label "has business process" ;
  rdfs:comment "Links an invoice message to a business process." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess .
:businessProcessOf a owl:ObjectProperty ;
  rdfs:label "business process of" ;
  rdfs:comment "Inverse of hasBusinessProcess." ;
  rdfs:domain :BusinessProcess ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasBusinessProcess .
:hasValidationConstraint a owl:ObjectProperty ;
  rdfs:label "has validation constraint" ;
  rdfs:comment "Links an invoice message to a validation constraint (e.g., SHACL rule)." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ValidationConstraint .
:validationConstraintOf a owl:ObjectProperty ;
  rdfs:label "validation constraint of" ;
  rdfs:comment "Inverse of hasValidationConstraint." ;
  rdfs:domain :ValidationConstraint ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasValidationConstraint .

#################################################################
# Data Properties
#################################################################
:hasGlobalLocationNumber a owl:DatatypeProperty ;
  rdfs:label "has Global Location Number" ;
  rdfs:comment "Links an organization to its GLN identifier." ;
  rdfs:domain :Organization ;
  rdfs:range xsd:string .
:hasGlobalLocationNumber a owl:FunctionalProperty .
:hasReferenceNumber a owl:DatatypeProperty ;
  rdfs:label "has reference number" ;
  rdfs:comment "Links an invoice message to its reference number." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range xsd:string .
:hasReferenceNumber a owl:FunctionalProperty .
:hasDate a owl:DatatypeProperty ;
  rdfs:label "has date" ;
  rdfs:comment "Links a DTM segment to a date value." ;
  rdfs:domain :DTMSegment ;
  rdfs:range xsd:string .
:hasDate a owl:FunctionalProperty .
:hasDateQualifier a owl:DatatypeProperty ;
  rdfs:label "has date qualifier" ;
