  rdfs:domain :DTMSegment ;
  rdfs:range xsd:string .
:hasDateQualifier a owl:FunctionalProperty .
:hasAmount a owl:DatatypeProperty ;
  rdfs:label "has amount" ;
  rdfs:comment "Links a MOA segment to a monetary amount." ;
  rdfs:domain :MOASegment ;
  rdfs:range xsd:decimal .
:hasAmount a owl:FunctionalProperty .
:hasAmountQualifier a owl:DatatypeProperty ;
  rdfs:label "has amount qualifier" ;
  rdfs:comment "Links a MOA segment to a qualifier indicating the type of amount (e.g., invoice total, line total)." ;
  rdfs:domain :MOASegment ;
  rdfs:range xsd:string .
:hasAmountQualifier a owl:FunctionalProperty .
:hasReference a owl:DatatypeProperty ;
  rdfs:label "has reference" ;
  rdfs:comment "Links an RFF segment to a reference value." ;
  rdfs:domain :RFFSegment ;
  rdfs:range xsd:string .
:hasReference a owl:FunctionalProperty .
:hasReferenceQualifier a owl:DatatypeProperty ;
  rdfs:label "has reference qualifier" ;
  rdfs:comment "Links an RFF segment to a qualifier indicating the type of reference (e.g., order, invoice)." ;
  rdfs:domain :RFFSegment ;
  rdfs:range xsd:string .
:hasReferenceQualifier a owl:FunctionalProperty .
:hasLineNumber a owl:DatatypeProperty ;
  rdfs:label "has line number" ;
  rdfs:comment "Links a LIN segment to the line item number." ;
  rdfs:domain :LINSegment ;
  rdfs:range xsd:integer .
:hasLineNumber a owl:FunctionalProperty .
:hasProductID a owl:DatatypeProperty ;
  rdfs:label "has product ID" ;
  rdfs:comment "Links a LIN segment to the primary product identifier." ;
  rdfs:domain :LINSegment ;
  rdfs:range xsd:string .
:hasAdditionalProductID a owl:DatatypeProperty ;
  rdfs:label "has additional product ID" ;
  rdfs:comment "Links a PIA segment to an additional product identifier." ;
  rdfs:domain :PIASegment ;
  rdfs:range xsd:string .
:hasQuantityValue a owl:DatatypeProperty ;
  rdfs:label "has quantity value" ;
  rdfs:comment "Links a QTY segment to the quantity value." ;
  rdfs:domain :QTYSegment ;
  rdfs:range xsd:decimal .
:hasQuantityValue a owl:FunctionalProperty .
:hasQuantityQualifier a owl:DatatypeProperty ;
  rdfs:label "has quantity qualifier" ;
  rdfs:comment "Links a QTY segment to a qualifier indicating the type of quantity (e.g., invoiced, ordered)." ;
  rdfs:domain :QTYSegment ;
  rdfs:range xsd:string .
:hasQuantityQualifier a owl:FunctionalProperty .
:hasUnitPrice a owl:DatatypeProperty ;
  rdfs:label "has unit price" ;
  rdfs:comment "Links a PRI segment to the unit price value." ;
  rdfs:domain :PRISegment ;
  rdfs:range xsd:decimal .
:hasUnitPrice a owl:FunctionalProperty .
:hasPriceQualifier a owl:DatatypeProperty ;
  rdfs:label "has price qualifier" ;
  rdfs:comment "Links a PRI segment to a qualifier indicating the type of price (e.g., net, gross)." ;
  rdfs:domain :PRISegment ;
  rdfs:range xsd:string .
:hasPriceQualifier a owl:FunctionalProperty .
:hasTaxType a owl:DatatypeProperty ;
  rdfs:label "has tax type" ;
  rdfs:comment "Links a TAX segment to the tax type." ;
  rdfs:domain :TAXSegment ;
  rdfs:range xsd:string .
:hasTaxType a owl:FunctionalProperty .
:hasTaxAmount a owl:DatatypeProperty ;
  rdfs:label "has tax amount" ;
  rdfs:comment "Links a TAX segment to the tax amount." ;
  rdfs:domain :TAXSegment ;
  rdfs:range xsd:decimal .
:hasTaxAmount a owl:FunctionalProperty .
:hasAllowanceChargeType a owl:DatatypeProperty ;
  rdfs:label "has allowance/charge type" ;
  rdfs:comment "Links an ALC segment to the type of allowance or charge." ;
  rdfs:domain :ALCSegment ;
  rdfs:range xsd:string .
:hasAllowanceChargeType a owl:FunctionalProperty .
:hasAllowanceChargeAmount a owl:DatatypeProperty ;
  rdfs:label "has allowance/charge amount" ;
  rdfs:comment "Links an ALC segment to the amount of allowance or charge." ;
  rdfs:domain :ALCSegment ;
  rdfs:range xsd:decimal .
:hasAllowanceChargeAmount a owl:FunctionalProperty .
:hasControlIndicator a owl:DatatypeProperty ;
  rdfs:label "has control indicator" ;
  rdfs:comment "Links a UNS segment to a control indicator (e.g., S for summary)." ;
  rdfs:domain :UNSSegment ;
  rdfs:range xsd:string .
:hasControlIndicator a owl:FunctionalProperty .
:hasName a owl:DatatypeProperty ;
  rdfs:label "has name" ;
  rdfs:comment "The name of an organization." ;
  rdfs:domain :Organization ;
  rdfs:range xsd:string .
:hasName a owl:FunctionalProperty .
:hasAddressLine a owl:DatatypeProperty ;
  rdfs:label "has address line" ;
  rdfs:comment "The address line for an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .
:hasAddressLine a owl:FunctionalProperty .
:hasPostalCode a owl:DatatypeProperty ;
  rdfs:label "has postal code" ;
  rdfs:comment "The postal code for an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .
:hasPostalCode a owl:FunctionalProperty .
:hasCity a owl:DatatypeProperty ;
  rdfs:label "has city" ;
  rdfs:comment "The city for an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .
:hasCity a owl:FunctionalProperty .
:hasCountry a owl:DatatypeProperty ;
  rdfs:label "has country" ;
  rdfs:comment "The country for an address." ;
  rdfs:domain :Address ;
  rdfs:range xsd:string .
:hasCountry a owl:FunctionalProperty .

#################################################################
# ReferenceNumber and GlobalLocationNumber connections
#################################################################
:hasReferenceNumberObject a owl:ObjectProperty ;
  rdfs:label "has reference number object" ;
  rdfs:comment "Links an invoice message to a ReferenceNumber instance." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ReferenceNumber .
:referenceNumberOf a owl:ObjectProperty ;
  rdfs:label "reference number of" ;
  rdfs:comment "Inverse of hasReferenceNumberObject." ;
  rdfs:domain :ReferenceNumber ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasReferenceNumberObject .
:hasGlobalLocationNumberObject a owl:ObjectProperty ;
  rdfs:label "has global location number object" ;
  rdfs:comment "Links an organization to a GlobalLocationNumber instance." ;
  rdfs:domain :Organization ;
  rdfs:range :GlobalLocationNumber .
:globalLocationNumberOf a owl:ObjectProperty ;
  rdfs:label "global location number of" ;
  rdfs:comment "Inverse of hasGlobalLocationNumberObject." ;
  rdfs:domain :GlobalLocationNumber ;
  rdfs:range :Organization ;
  owl:inverseOf :hasGlobalLocationNumberObject .

#################################################################
# Disjointness and Unions
#################################################################
:Organization owl:disjointWith :Item .
:Address owl:disjointWith :Organization .
:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Segment owl:disjointUnionOf ( :BGMSegment :NADSegment :DTMSegment :MOASegment :RFFSegment :LINSegment :PIASegment :QTYSegment :PRISegment :TAXSegment :ALCSegment :UNSSegment :HeaderSection :DetailSection :SummarySection ) .

#################################################################
# End of Ontology
#################################################################
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#storyid> a owl:Ontology ;
  rdfs:label "EDIFACT D96A INVOIC Ontology" ;
  rdfs:comment "A profound OWL ontology for the UN/EDIFACT D96A INVOIC message, including all foundational and mandatory segments, roles, and data structures as per EANCOM, EN 16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope a owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "The EDIFACT interchange envelope, containing one or more messages." .
:Message a owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A digital business message within an interchange envelope." .
:InvoiceMessage a owl:Class ;
  rdfs:subClassOf :Message ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An EDIFACT INVOIC message for global trade transactions." .
:Segment a owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A logical segment within an EDIFACT message." .
:BGMSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." .
:NADSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." .
:DTMSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "DTM Segment" ;
  rdfs:comment "Date/Time/Period segment for document and delivery dates." .
:MOASegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "MOA Segment" ;
  rdfs:comment "Monetary Amount segment for invoice and line item amounts." .
:RFFSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "RFF Segment" ;
  rdfs:comment "Reference segment for document and order references." .
:LINSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "LIN Segment" ;
  rdfs:comment "Line Item segment for item identification." .
:PIASegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PIA Segment" ;
  rdfs:comment "Additional Product ID segment for alternative item codes." .
:QTYSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "QTY Segment" ;
  rdfs:comment "Quantity segment for line item quantities." .
:PRISegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PRI Segment" ;
  rdfs:comment "Price segment for unit prices." .
:TAXSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "TAX Segment" ;
  rdfs:comment "Tax segment for tax breakdowns." .
:ALCSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "ALC Segment" ;
  rdfs:comment "Allowance or Charge segment for discounts or surcharges." .
:UNSSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "UNS Segment" ;
  rdfs:comment "Section Control segment for totals separation." .
:CompositeDataElement a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element in a segment." .
:SimpleDataElement a owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element within a composite." .
:HeaderSection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice message." .
:DetailSection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section with line items." .
:SummarySection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section with totals and taxes." .
:Organization a owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "A party involved in the invoice, potentially in multiple roles." .
:AgentRole a owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Supplier)." .
:BuyerRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Buyer Role" ;
  rdfs:comment "Role of the buyer in the invoice." .
:DeliveryPartyRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Delivery Party Role" ;
  rdfs:comment "Role of the delivery party in the invoice." .
:Address a owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "A postal or physical address for an organization." .
:GlobalLocationNumber a owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A unique identifier for an organization's location." .
:Item a owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A product or service sold in the invoice." .
:Price a owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "A price associated with an item." .
:Quantity a owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "A quantity of an item." .
:Tax a owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "A tax breakdown for the invoice or line item." .
:BusinessProcess a owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "A business process to which the invoice can be assigned." .
:ValidationConstraint a owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "A constraint for automated validation (e.g., SHACL rule)." .
:LineItem a owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A pivot class for reifying the sale of an item with price and quantity." ;
  owl:equivalentClass [ a owl:Restriction ; owl:onProperty :describesItem ; owl:someValuesFrom :Item ] .
:RoleAssignment a owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "A pivot class reifying an organization-role-address relationship." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:allValuesFrom :AgentRole ] .
:InvoiceAmount a owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "The total invoice amount." .
:ReferenceNumber a owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "A reference number for the invoice or related document." .

#################################################################
# Object Properties
#################################################################
:containsMessage a owl:ObjectProperty ;
  rdfs:label "contains message" ;
  rdfs:comment "Links an interchange envelope to a message." ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message .
:containsMessage a owl:FunctionalProperty .
:containedInEnvelope a owl:ObjectProperty ;
  rdfs:label "contained in envelope" ;
  rdfs:comment "Inverse of containsMessage." ;
  rdfs:domain :Message ;
  rdfs:range :InterchangeEnvelope ;
  owl:inverseOf :containsMessage .
:hasSegment a owl:ObjectProperty ;
  rdfs:label "has segment" ;
  rdfs:comment "Links a message to its segments." ;
  rdfs:domain :Message ;
  rdfs:range :Segment .
:hasSegment a owl:FunctionalProperty .
:segmentOf a owl:ObjectProperty ;
  rdfs:label "segment of" ;
  rdfs:comment "Inverse of hasSegment." ;
  rdfs:domain :Segment ;
  rdfs:range :Message ;
  owl:inverseOf :hasSegment .
:hasHeaderSection a owl:ObjectProperty ;
  rdfs:label "has header section" ;
  rdfs:comment "Links an invoice message to its header section." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :HeaderSection .
:hasHeaderSection a owl:FunctionalProperty .
:headerSectionOf a owl:ObjectProperty ;
  rdfs:label "header section of" ;
  rdfs:comment "Inverse of hasHeaderSection." ;
  rdfs:domain :HeaderSection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasHeaderSection .
:hasDetailSection a owl:ObjectProperty ;
  rdfs:label "has detail section" ;
  rdfs:comment "Links an invoice message to its detail section." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :DetailSection .
:hasDetailSection a owl:FunctionalProperty .
:detailSectionOf a owl:ObjectProperty ;
  rdfs:label "detail section of" ;
  rdfs:comment "Inverse of hasDetailSection." ;
  rdfs:domain :DetailSection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasDetailSection .
:hasSummarySection a owl:ObjectProperty ;
  rdfs:label "has summary section" ;
  rdfs:comment "Links an invoice message to its summary section." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :SummarySection .
:hasSummarySection a owl:FunctionalProperty .
:summarySectionOf a owl:ObjectProperty ;
  rdfs:label "summary section of" ;
  rdfs:comment "Inverse of hasSummarySection." ;
  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasSummarySection .
:hasLineItem a owl:ObjectProperty ;
  rdfs:label "has line item" ;
  rdfs:comment "Links a detail section to a line item." ;
  rdfs:domain :DetailSection ;
  rdfs:range :LineItem .
:lineItemOf a owl:ObjectProperty ;
  rdfs:label "line item of" ;
  rdfs:comment "Inverse of hasLineItem." ;
  rdfs:domain :LineItem ;
  rdfs:range :DetailSection ;
  owl:inverseOf :hasLineItem .
:describesItem a owl:ObjectProperty ;
  rdfs:label "describes item" ;
  rdfs:comment "Links a line item to the item being sold." ;
  rdfs:domain :LineItem ;
  rdfs:range :Item .
:itemDescribedBy a owl:ObjectProperty ;
  rdfs:label "item described by" ;
  rdfs:comment "Inverse of describesItem." ;
  rdfs:domain :Item ;
  rdfs:range :LineItem ;
  owl:inverseOf :describesItem .
:hasNetPrice a owl:ObjectProperty ;
  rdfs:label "has net price" ;
  rdfs:comment "Links a line item to its net price." ;
  rdfs:domain :LineItem ;
  rdfs:range :Price .
:hasNetPrice a owl:FunctionalProperty .
:netPriceOf a owl:ObjectProperty ;
  rdfs:label "net price of" ;
  rdfs:comment "Inverse of hasNetPrice." ;
  rdfs:domain :Price ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasNetPrice .
:hasQuantity a owl:ObjectProperty ;
  rdfs:label "has quantity" ;
  rdfs:comment "Links a line item to its quantity." ;
  rdfs:domain :LineItem ;
  rdfs:range :Quantity .
:hasQuantity a owl:FunctionalProperty .
:quantityOf a owl:ObjectProperty ;
  rdfs:label "quantity of" ;
  rdfs:comment "Inverse of hasQuantity." ;
  rdfs:domain :Quantity ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasQuantity .
:involvesOrganization a owl:ObjectProperty ;
  rdfs:label "involves organization" ;
  rdfs:comment "Links an invoice message to an involved organization." ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :Organization .
:organizationInvolvedIn a owl:ObjectProperty ;
  rdfs:label "organization involved in" ;
  rdfs:comment "Inverse of involvesOrganization." ;
  rdfs:domain :Organization ;
  rdfs:range :InvoiceMessage ;
