  rdfs:range :SummarySection .
:hasSummarySection a owl:FunctionalProperty .
:summarySectionOf a owl:ObjectProperty ;
  rdfs:label "summary section of" ;
  rdfs:comment "The summary section is part of an invoice message (inverse of hasSummarySection)." ;
  rdfs:domain :SummarySection ;
  rdfs:range :InvoiceMessage ;
  owl:inverseOf :hasSummarySection .
:hasLineItem a owl:ObjectProperty ;
  rdfs:label "has line item" ;
  rdfs:comment "Links a detail section to a line item." ;
