  rdfs:comment "Links a line item to the item being sold." ;
  rdfs:domain :LineItem ;
  rdfs:range :Item .
:itemDescribedBy a owl:ObjectProperty ;
  rdfs:label "item described by" ;
  rdfs:comment "Inverse of describesItem." ;
  rdfs:domain :Item ;
  rdfs:range :LineItem ;
  owl:inverseOf :describesItem .
:hasNetPrice a owl:ObjectProperty ;
  rdfs:label "has net price" ;
  rdfs:comment "Links a line item to its net price." ;
  rdfs:domain :LineItem ;
  rdfs:range :Price .
:hasNetPrice a owl:FunctionalProperty .
:netPriceOf a owl:ObjectProperty ;
  rdfs:label "net price of" ;
  rdfs:comment "Inverse of hasNetPrice." ;
  rdfs:domain :Price ;
  rdfs:range :LineItem ;
  owl:inverseOf :hasNetPrice .
:hasQuantity a owl:ObjectProperty ;
  rdfs:label "has quantity" ;
