:Segment owl:disjointUnionOf ( :BGMSegment :NADSegment :DTMSegment :MOASegment :RFFSegment :LINSegment :PIASegment :QTYSegment :PRISegment :TAXSegment :ALCSegment :UNSSegment :HeaderSection :DetailSection :SummarySection ) .

