<http://www.example.org/ontology#storyid> a owl:Ontology ;
  rdfs:label "EDIFACT D96A INVOIC Ontology" ;
  rdfs:comment "A profound OWL ontology for the UN/EDIFACT D96A INVOIC message, including all foundational and mandatory segments, roles, and data structures as per EANCOM, EN 16931-1, and P2P-O alignment." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope a owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "The EDIFACT interchange envelope, containing one or more messages." .
:Message a owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A digital business message within an interchange envelope." .
:InvoiceMessage a owl:Class ;
  rdfs:subClassOf :Message ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An EDIFACT INVOIC message for global trade transactions." .
:Segment a owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A logical segment within an EDIFACT message." .
:BGMSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." .
:NADSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." .
:DTMSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "DTM Segment" ;
  rdfs:comment "Date/Time/Period segment for document and delivery dates." .
:MOASegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "MOA Segment" ;
  rdfs:comment "Monetary Amount segment for invoice and line item amounts." .
:RFFSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "RFF Segment" ;
  rdfs:comment "Reference segment for document and order references." .
:LINSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "LIN Segment" ;
  rdfs:comment "Line Item segment for item identification." .
:PIASegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PIA Segment" ;
  rdfs:comment "Additional Product ID segment for alternative item codes." .
:QTYSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "QTY Segment" ;
  rdfs:comment "Quantity segment for line item quantities." .
:PRISegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "PRI Segment" ;
  rdfs:comment "Price segment for unit prices." .
:TAXSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "TAX Segment" ;
  rdfs:comment "Tax segment for tax breakdowns." .
:ALCSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "ALC Segment" ;
  rdfs:comment "Allowance or Charge segment for discounts or surcharges." .
:UNSSegment a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "UNS Segment" ;
  rdfs:comment "Section Control segment for totals separation." .
:CompositeDataElement a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element in a segment." .
:SimpleDataElement a owl:Class ;
  rdfs:subClassOf :CompositeDataElement ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element within a composite." .
:HeaderSection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of the invoice message." .
:DetailSection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section with line items." .
:SummarySection a owl:Class ;
  rdfs:subClassOf :Segment ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section with totals and taxes." .
:Organization a owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "A party involved in the invoice, potentially in multiple roles." .
:AgentRole a owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Supplier)." .
:BuyerRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Buyer Role" ;
  rdfs:comment "Role of the buyer in the invoice." .
:DeliveryPartyRole a owl:Class ;
  rdfs:subClassOf :AgentRole ;
  rdfs:label "Delivery Party Role" ;
  rdfs:comment "Role of the delivery party in the invoice." .
:Address a owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "A postal or physical address for an organization." .
:GlobalLocationNumber a owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A unique identifier for an organization's location." .
:Item a owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "A product or service sold in the invoice." .
:Price a owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "A price associated with an item." .
:Quantity a owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "A quantity of an item." .
:Tax a owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "A tax breakdown for the invoice or line item." .
:BusinessProcess a owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "A business process to which the invoice can be assigned." .
:ValidationConstraint a owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "A constraint for automated validation (e.g., SHACL rule)." .
:LineItem a owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A pivot class for reifying the sale of an item with price and quantity." ;
  owl:equivalentClass [ a owl:Restriction ; owl:onProperty :describesItem ; owl:someValuesFrom :Item ] .
:RoleAssignment a owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "A pivot class reifying an organization-role-address relationship." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:allValuesFrom :AgentRole ] .
:InvoiceAmount a owl:Class ;
  rdfs:label "Invoice Amount" ;
  rdfs:comment "The total invoice amount." .
:ReferenceNumber a owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "A reference number for the invoice or related document." .

