    owl:inverseOf :isDetailSectionOfInvoice .

:isDetailSectionOfInvoice a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is detail section of invoice" ;
    rdfs:comment "Inverse property: relates a detail section to its invoice message." .

:hasSummarySection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    rdfs:label "has summary section" ;
    rdfs:comment "Relates an invoice message to its summary section." ;
    owl:inverseOf :isSummarySectionOfInvoice .

:isSummarySectionOfInvoice a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is summary section of invoice" ;
    rdfs:comment "Inverse property: relates a summary section to its invoice message." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Relates a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOfSegment .

:isCompositeElementOfSegment a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of segment" ;
    rdfs:comment "Inverse property: relates a composite element to its parent segment." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a composite element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOfComposite .

:isSimpleElementOfComposite a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of composite" ;
    rdfs:comment "Inverse property: relates a simple element to its parent composite." .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "plays role assignment" ;
    rdfs:comment "Links an organization to its role assignments." ;
    owl:inverseOf :isRolePlayedByOrganization .

:isRolePlayedByOrganization a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role played by organization" ;
    rdfs:comment "Inverse property: links a role assignment to its organization." .

:hasRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "has role" ;
    rdfs:comment "Links a role assignment to an agent role (e.g., Buyer, Supplier)." ;
    owl:inverseOf :isRoleOfAssignment .

:isRoleOfAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is role of assignment" ;
    rdfs:comment "Inverse property: links an agent role to its role assignment." .

:inContextOfInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "in context of invoice" ;
    rdfs:comment "Links a role assignment to its invoice message context." ;
    owl:inverseOf :hasRoleAssignmentInInvoice .

:hasRoleAssignmentInInvoice a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment in invoice" ;
    rdfs:comment "Inverse property: links an invoice message to its role assignment." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse property: links an address to its organization." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifiers (e.g., GLN)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Inverse property: links an identifier to its organization." .

:hasLineItem a owl:ObjectProperty ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "has line item" ;
    rdfs:comment "Links a detail section to its line items." ;
    owl:inverseOf :isLineItemOfDetailSection .

:isLineItemOfDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    rdfs:label "is line item of detail section" ;
    rdfs:comment "Inverse property: links a line item to its detail section." .

:describesItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a line item to the described item." ;
    owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is described by line item" ;
    rdfs:comment "Inverse property: links an item to its line item description." .

:hasNetPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceForLineItem .

:isNetPriceForLineItem a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    rdfs:label "is net price for line item" ;
    rdfs:comment "Inverse property: links a price to its line item." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a summary section to its taxes." ;
    owl:inverseOf :isTaxOfSummarySection .

:isTaxOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    rdfs:label "is tax of summary section" ;
    rdfs:comment "Inverse property: links a tax to its summary section." .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range :Price ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links a summary section to the invoice total amount." ;
    owl:inverseOf :isInvoiceAmountOfSummarySection .

:isInvoiceAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :SummarySection ;
    rdfs:label "is invoice amount of summary section" ;
    rdfs:comment "Inverse property: links a price to its summary section." .

:isAssignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is assigned to business process" ;
    rdfs:comment "Inverse property: links a business process to its assigned invoice message." ;
    owl:inverseOf :assignedBusinessProcessOf .

:assignedBusinessProcessOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "assigned business process of" ;
    rdfs:comment "Inverse property: links an invoice message to its assigned business process." .

:isValidatedBy a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is validated by" ;
    rdfs:comment "Inverse property: links a validation constraint to its invoice message." ;
    owl:inverseOf :validatedByConstraint .

:validatedByConstraint a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "validated by constraint" ;
    rdfs:comment "Inverse property: links an invoice message to its validation constraint." .

:p2pEquivalent a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :P2PConcept ;
    rdfs:range owl:Thing ;
    rdfs:label "P2P-O equivalent" ;
    rdfs:comment "Indicates the equivalent P2P-O concept." ;
    owl:inverseOf :hasP2PConceptEquivalent .

:hasP2PConceptEquivalent a owl:ObjectProperty ;
    rdfs:domain owl:Thing ;
    rdfs:range :P2PConcept ;
    rdfs:label "has P2P concept equivalent" ;
    rdfs:comment "Inverse property: links a concept to its P2P-O equivalent." .

#################################################################
# Data Properties
#################################################################
:hasGLN a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN" ;
    rdfs:comment "The GLN string value for an organization." .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :BGMSegment ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Invoice number as found in BGM segment." .

:hasDocumentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has document date" ;
    rdfs:comment "The document date in the header section." .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number in the header section." .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of the item in a line item." .

#################################################################
# Restrictions & Axioms
#################################################################
# OrganizationRoleAssignment reifies Organization, AgentRole, and InvoiceMessage
:OrganizationRoleAssignment owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
        [ a owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ]
        [ a owl:Restriction ; owl:onProperty :inContextOfInvoice ; owl:someValuesFrom :InvoiceMessage ]
    )
] .

# InvoiceMessage must have header, detail, and summary sections
:InvoiceMessage rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasHeaderSection ; owl:someValuesFrom :HeaderSection ] ,
                                   [ a owl:Restriction ; owl:onProperty :hasDetailSection ; owl:someValuesFrom :DetailSection ] ,
                                   [ a owl:Restriction ; owl:onProperty :hasSummarySection ; owl:someValuesFrom :SummarySection ] .

# DetailSection must have at least one line item
:DetailSection rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasLineItem ; owl:someValuesFrom :LineItem ] .

# LineItem must describe an item and have a net price
:LineItem rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :describesItem ; owl:someValuesFrom :Item ] ,
                          [ a owl:Restriction ; owl:onProperty :hasNetPrice ; owl:someValuesFrom :Price ] .

# SummarySection must have invoice amount
:SummarySection rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasInvoiceAmount ; owl:someValuesFrom :Price ] .

# Organization must have at least one identifier
:Organization rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasIdentifier ; owl:someValuesFrom :Identifier ] .

# Address is functional for an Organization
:Organization rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:maxCardinality "1"^^xsd:nonNegativeInteger ] .

#################################################################
# Disjointness
#################################################################
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item , :Address , :Identifier .
:Item owl:disjointWith :Price .
:Price owl:disjointWith :Tax .

#################################################################
# Individuals (Examples)
#################################################################
:Buyer a :AgentRole ;
    rdfs:label "Buyer" ;
    rdfs:comment "Role of buyer in invoice context." .

:Supplier a :AgentRole ;
    rdfs:label "Supplier" ;
    rdfs:comment "Role of supplier in invoice context." .
"}

