#################################################################
# Hierarchies, Disjoint, and DisjointUnion
#################################################################
:InterchangeEnvelope owl:disjointWith :Message .
:Message owl:disjointWith :Segment .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:Organization owl:disjointWith :Item .
:Address owl:disjointWith :Identifier .
:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Complex Axioms & Restrictions
#################################################################
:InvoiceMessage owl:equivalentClass [ rdf:type owl:Class ;
  owl:intersectionOf (
    [ rdf:type owl:Restriction ; owl:onProperty :hasSection ; owl:allValuesFrom :Segment ]
    [ rdf:type owl:Restriction ; owl:onProperty :hasBusinessProcess ; owl:someValuesFrom :BusinessProcess ]
  )
] .

:RoleAssignment owl:equivalentClass [ rdf:type owl:Class ;
  owl:intersectionOf (
    [ rdf:type owl:Restriction ; owl:onProperty :hasRole ; owl:allValuesFrom :AgentRole ]
    [ rdf:type owl:Restriction ; owl:onProperty :inContextOf ; owl:allValuesFrom :InvoiceMessage ]
  )
] .

:LineItem owl:equivalentClass [ rdf:type owl:Class ;
  owl:intersectionOf (
    [ rdf:type owl:Restriction ; owl:onProperty :describesItem ; owl:allValuesFrom :Item ]
    [ rdf:type owl:Restriction ; owl:onProperty :hasNetPrice ; owl:allValuesFrom :Price ]
    [ rdf:type owl:Restriction ; owl:onProperty :hasQuantity ; owl:allValuesFrom :Quantity ]
  )
] .

