  owl:inverseOf :isQuantityOf .

:isQuantityOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Quantity ;
  rdfs:range :LineItem ;
  rdfs:label "is quantity of" ;
  rdfs:comment "Inverse of hasQuantity: relates a quantity to the line item it is for." ;
  owl:inverseOf :hasQuantity .

:hasTax rdf:type owl:ObjectProperty ;
  rdfs:domain :SummarySection ;
