# Object Properties and Inverses
#################################################################
:containsMessage rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  rdfs:label "contains message" ;
  rdfs:comment "Relates an interchange envelope to the messages it contains." ;
  owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope rdf:type owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :InterchangeEnvelope ;
  rdfs:label "is contained in envelope" ;
  rdfs:comment "Inverse of containsMessage: relates a message to the envelope that contains it." ;
  owl:inverseOf :containsMessage .

:hasSegment rdf:type owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :Segment ;
  rdfs:label "has segment" ;
  rdfs:comment "Relates a message to its constituent segments." ;
  owl:inverseOf :isSegmentOf .

:isSegmentOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :Message ;
  rdfs:label "is segment of" ;
  rdfs:comment "Inverse of hasSegment: relates a segment to the message it is part of." ;
  owl:inverseOf :hasSegment .

:hasSection rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :Segment ;
  rdfs:label "has section" ;
  rdfs:comment "Relates an invoice message to its header, detail, and summary sections." ;
  owl:inverseOf :isSectionOf .

:isSectionOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is section of" ;
  rdfs:comment "Inverse of hasSection: relates a section to its invoice message." ;
  owl:inverseOf :hasSection .

:hasCompositeElement rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "has composite element" ;
  rdfs:comment "Relates a segment to its composite data elements." ;
  owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf rdf:type owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :Segment ;
  rdfs:label "is composite element of" ;
  rdfs:comment "Inverse of hasCompositeElement: relates a composite data element to its segment." ;
  owl:inverseOf :hasCompositeElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :SimpleDataElement ;
  rdfs:label "has simple element" ;
  rdfs:comment "Relates a composite data element to its simple data elements." ;
  owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf rdf:type owl:ObjectProperty ;
  rdfs:domain :SimpleDataElement ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "is simple element of" ;
  rdfs:comment "Inverse of hasSimpleElement: relates a simple data element to its composite data element." ;
  owl:inverseOf :hasSimpleElement .

:playsRole rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  rdfs:label "plays role" ;
  rdfs:comment "Relates an organization to its role assignment in a transaction." ;
  owl:inverseOf :rolePlayedBy .

:rolePlayedBy rdf:type owl:ObjectProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "role played by" ;
  rdfs:comment "Inverse of playsRole: relates a role assignment to the organization that plays it." ;
  owl:inverseOf :playsRole .

:hasRole rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :AgentRole ;
  rdfs:label "has role" ;
  rdfs:comment "Specifies the agent role played in a role assignment." ;
  owl:inverseOf :isRoleOf .

:isRoleOf rdf:type owl:ObjectProperty ;
  rdfs:domain :AgentRole ;
  rdfs:range :RoleAssignment ;
  rdfs:label "is role of" ;
  rdfs:comment "Inverse of hasRole: relates an agent role to the role assignment it is part of." ;
  owl:inverseOf :hasRole .

:inContextOf rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "in context of" ;
  rdfs:comment "Specifies the invoice message context for a role assignment." ;
  owl:inverseOf :contextHasRoleAssignment .

:contextHasRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :RoleAssignment ;
  rdfs:label "context has role assignment" ;
  rdfs:comment "Inverse of inContextOf: relates an invoice message to its role assignments." ;
  owl:inverseOf :inContextOf .

:hasAddress rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  rdfs:label "has address" ;
  rdfs:comment "Relates an organization to its address." ;
  owl:inverseOf :isAddressOf .

:isAddressOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Address ;
  rdfs:range :Organization ;
  rdfs:label "is address of" ;
  rdfs:comment "Inverse of hasAddress: relates an address to the organization it belongs to." ;
  owl:inverseOf :hasAddress .

:hasIdentifier rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Identifier ;
  rdfs:label "has identifier" ;
  rdfs:comment "Relates an organization to its identifier." ;
  owl:inverseOf :isIdentifierOf .

:isIdentifierOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Identifier ;
  rdfs:range :Organization ;
  rdfs:label "is identifier of" ;
  rdfs:comment "Inverse of hasIdentifier: relates an identifier to the organization it belongs to." ;
  owl:inverseOf :hasIdentifier .

:isBuyer rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "is buyer" ;
  rdfs:comment "Specifies the buyer organization in a role assignment." ;
  owl:inverseOf :buyerRoleAssignment .

:buyerRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  rdfs:label "buyer role assignment" ;
  rdfs:comment "Inverse of isBuyer: relates an organization to the buyer role assignment." ;
  owl:inverseOf :isBuyer .

