:isReferencedByInvoiceMessage rdf:type owl:ObjectProperty ;
  rdfs:domain :P2POntologyReference ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is referenced by invoice message" ;
  rdfs:comment "Inverse of referencesP2PO: relates a P2P-O reference to the invoice message that references it." ;
  owl:inverseOf :referencesP2PO .

:validatedBySHACL rdf:type owl:ObjectProperty ;
