  rdfs:comment "A business message within an interchange envelope." .

:InvoiceMessage rdf:type owl:Class ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An invoice message, such as INVOIC, within the interchange envelope." ;
  rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment rdf:type owl:Class ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." ;
  rdfs:subClassOf :Segment .

:NADSegment rdf:type owl:Class ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." ;
  rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element within a composite data element." .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of an invoice message, containing dates and reference numbers." ;
  rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing individual line items." ;
  rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section providing totals and tax information." ;
  rdfs:subClassOf :Segment .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "An organization involved in the invoice, such as buyer or delivery party." .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in a transaction." .

:RoleAssignment rdf:type owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "A pivot class for reification of organization roles in invoice context." .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address of an organization." .

:Identifier rdf:type owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "An identifier for an organization." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A global location number identifier." ;
  rdfs:subClassOf :Identifier .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price information for items or invoices." .

:Quantity rdf:type owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "Quantity of items sold." .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A line item in the invoice detail section." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary section." .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for document identification." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "Business process assignment for the invoice." .

:ValidationConstraint rdf:type owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "Constraint for validating invoice messages." .

:EN16931Requirement rdf:type owl:Class ;
  rdfs:label "EN 16931 Requirement" ;
  rdfs:comment "A requirement from EN 16931-1 standard." .

:P2POntologyReference rdf:type owl:Class ;
  rdfs:label "P2P-O Reference" ;
  rdfs:comment "Reference to the Purchase-to-Pay Ontology." .

:SHACLConstraint rdf:type owl:Class ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "SHACL constraint for automated validation." .

#################################################################
# Object Properties and Inverses
#################################################################
:containsMessage rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  rdfs:label "contains message" ;
  rdfs:comment "Relates an interchange envelope to the messages it contains." ;
  owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope rdf:type owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :InterchangeEnvelope ;
  rdfs:label "is contained in envelope" ;
  rdfs:comment "Inverse of containsMessage: relates a message to the envelope that contains it." ;
  owl:inverseOf :containsMessage .

:hasSegment rdf:type owl:ObjectProperty ;
  rdfs:domain :Message ;
  rdfs:range :Segment ;
  rdfs:label "has segment" ;
  rdfs:comment "Relates a message to its constituent segments." ;
  owl:inverseOf :isSegmentOf .

:isSegmentOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :Message ;
  rdfs:label "is segment of" ;
  rdfs:comment "Inverse of hasSegment: relates a segment to the message it is part of." ;
  owl:inverseOf :hasSegment .

:hasSection rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :Segment ;
  rdfs:label "has section" ;
  rdfs:comment "Relates an invoice message to its header, detail, and summary sections." ;
  owl:inverseOf :isSectionOf .

:isSectionOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is section of" ;
  rdfs:comment "Inverse of hasSection: relates a section to its invoice message." ;
  owl:inverseOf :hasSection .

:hasCompositeElement rdf:type owl:ObjectProperty ;
  rdfs:domain :Segment ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "has composite element" ;
  rdfs:comment "Relates a segment to its composite data elements." ;
  owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf rdf:type owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :Segment ;
  rdfs:label "is composite element of" ;
  rdfs:comment "Inverse of hasCompositeElement: relates a composite data element to its segment." ;
  owl:inverseOf :hasCompositeElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
  rdfs:domain :CompositeDataElement ;
  rdfs:range :SimpleDataElement ;
  rdfs:label "has simple element" ;
  rdfs:comment "Relates a composite data element to its simple data elements." ;
  owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf rdf:type owl:ObjectProperty ;
  rdfs:domain :SimpleDataElement ;
  rdfs:range :CompositeDataElement ;
  rdfs:label "is simple element of" ;
  rdfs:comment "Inverse of hasSimpleElement: relates a simple data element to its composite data element." ;
  owl:inverseOf :hasSimpleElement .

:playsRole rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  rdfs:label "plays role" ;
  rdfs:comment "Relates an organization to its role assignment in a transaction." ;
  owl:inverseOf :rolePlayedBy .

:rolePlayedBy rdf:type owl:ObjectProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "role played by" ;
  rdfs:comment "Inverse of playsRole: relates a role assignment to the organization that plays it." ;
  owl:inverseOf :playsRole .

:hasRole rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :AgentRole ;
  rdfs:label "has role" ;
  rdfs:comment "Specifies the agent role played in a role assignment." ;
  owl:inverseOf :isRoleOf .

:isRoleOf rdf:type owl:ObjectProperty ;
  rdfs:domain :AgentRole ;
  rdfs:range :RoleAssignment ;
  rdfs:label "is role of" ;
  rdfs:comment "Inverse of hasRole: relates an agent role to the role assignment it is part of." ;
  owl:inverseOf :hasRole .

:inContextOf rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "in context of" ;
  rdfs:comment "Specifies the invoice message context for a role assignment." ;
  owl:inverseOf :contextHasRoleAssignment .

:contextHasRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :RoleAssignment ;
  rdfs:label "context has role assignment" ;
  rdfs:comment "Inverse of inContextOf: relates an invoice message to its role assignments." ;
  owl:inverseOf :inContextOf .

:hasAddress rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Address ;
  rdfs:label "has address" ;
  rdfs:comment "Relates an organization to its address." ;
  owl:inverseOf :isAddressOf .

:isAddressOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Address ;
  rdfs:range :Organization ;
  rdfs:label "is address of" ;
  rdfs:comment "Inverse of hasAddress: relates an address to the organization it belongs to." ;
  owl:inverseOf :hasAddress .

:hasIdentifier rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :Identifier ;
  rdfs:label "has identifier" ;
  rdfs:comment "Relates an organization to its identifier." ;
  owl:inverseOf :isIdentifierOf .

:isIdentifierOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Identifier ;
  rdfs:range :Organization ;
  rdfs:label "is identifier of" ;
  rdfs:comment "Inverse of hasIdentifier: relates an identifier to the organization it belongs to." ;
  owl:inverseOf :hasIdentifier .

:isBuyer rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "is buyer" ;
  rdfs:comment "Specifies the buyer organization in a role assignment." ;
  owl:inverseOf :buyerRoleAssignment .

:buyerRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  rdfs:label "buyer role assignment" ;
  rdfs:comment "Inverse of isBuyer: relates an organization to the buyer role assignment." ;
  owl:inverseOf :isBuyer .

:isDeliveryParty rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :RoleAssignment ;
  rdfs:range :Organization ;
  rdfs:label "is delivery party" ;
  rdfs:comment "Specifies the delivery party organization in a role assignment." ;
  owl:inverseOf :deliveryPartyRoleAssignment .

:deliveryPartyRoleAssignment rdf:type owl:ObjectProperty ;
  rdfs:domain :Organization ;
  rdfs:range :RoleAssignment ;
  rdfs:label "delivery party role assignment" ;
  rdfs:comment "Inverse of isDeliveryParty: relates an organization to the delivery party role assignment." ;
  owl:inverseOf :isDeliveryParty .

:hasLineItem rdf:type owl:ObjectProperty ;
  rdfs:domain :DetailSection ;
  rdfs:range :LineItem ;
  rdfs:label "has line item" ;
  rdfs:comment "Relates the detail section to its line items." ;
  owl:inverseOf :isLineItemOf .

:isLineItemOf rdf:type owl:ObjectProperty ;
  rdfs:domain :LineItem ;
  rdfs:range :DetailSection ;
  rdfs:label "is line item of" ;
  rdfs:comment "Inverse of hasLineItem: relates a line item to the detail section it belongs to." ;
  owl:inverseOf :hasLineItem .

:describesItem rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :LineItem ;
  rdfs:range :Item ;
  rdfs:label "describes item" ;
  rdfs:comment "Relates a line item to the item it describes." ;
  owl:inverseOf :isDescribedByLineItem .

:isDescribedByLineItem rdf:type owl:ObjectProperty ;
  rdfs:domain :Item ;
  rdfs:range :LineItem ;
  rdfs:label "is described by line item" ;
  rdfs:comment "Inverse of describesItem: relates an item to the line item that describes it." ;
  owl:inverseOf :describesItem .

:hasNetPrice rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :LineItem ;
  rdfs:range :Price ;
  rdfs:label "has net price" ;
  rdfs:comment "Relates a line item to its net price." ;
  owl:inverseOf :isNetPriceOf .

:isNetPriceOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Price ;
  rdfs:range :LineItem ;
  rdfs:label "is net price of" ;
  rdfs:comment "Inverse of hasNetPrice: relates a price to the line item it is the net price for." ;
  owl:inverseOf :hasNetPrice .

:hasQuantity rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :LineItem ;
  rdfs:range :Quantity ;
  rdfs:label "has quantity" ;
  rdfs:comment "Relates a line item to its quantity." ;
  owl:inverseOf :isQuantityOf .

:isQuantityOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Quantity ;
  rdfs:range :LineItem ;
  rdfs:label "is quantity of" ;
  rdfs:comment "Inverse of hasQuantity: relates a quantity to the line item it is for." ;
  owl:inverseOf :hasQuantity .

:hasTax rdf:type owl:ObjectProperty ;
  rdfs:domain :SummarySection ;
  rdfs:range :Tax ;
  rdfs:label "has tax" ;
  rdfs:comment "Relates the summary section to tax information." ;
  owl:inverseOf :isTaxOf .

:isTaxOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Tax ;
  rdfs:range :SummarySection ;
  rdfs:label "is tax of" ;
  rdfs:comment "Inverse of hasTax: relates a tax to the summary section it is part of." ;
  owl:inverseOf :hasTax .

:hasInvoiceAmount rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :SummarySection ;
  rdfs:range :Price ;
  rdfs:label "has invoice amount" ;
  rdfs:comment "Relates the summary section to the total invoice amount." ;
  owl:inverseOf :isInvoiceAmountOf .

:isInvoiceAmountOf rdf:type owl:ObjectProperty ;
  rdfs:domain :Price ;
  rdfs:range :SummarySection ;
  rdfs:label "is invoice amount of" ;
  rdfs:comment "Inverse of hasInvoiceAmount: relates a price to the summary section it is the total for." ;
  owl:inverseOf :hasInvoiceAmount .

:hasReferenceNumber rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :HeaderSection ;
  rdfs:range :ReferenceNumber ;
  rdfs:label "has reference number" ;
  rdfs:comment "Relates the header section to a reference number." ;
  owl:inverseOf :isReferenceNumberOf .

:isReferenceNumberOf rdf:type owl:ObjectProperty ;
  rdfs:domain :ReferenceNumber ;
  rdfs:range :HeaderSection ;
  rdfs:label "is reference number of" ;
  rdfs:comment "Inverse of hasReferenceNumber: relates a reference number to the header section it identifies." ;
  owl:inverseOf :hasReferenceNumber .

:hasBusinessProcess rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :BusinessProcess ;
  rdfs:label "has business process" ;
  rdfs:comment "Assigns a business process to the invoice message." ;
  owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf rdf:type owl:ObjectProperty ;
  rdfs:domain :BusinessProcess ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is business process of" ;
  rdfs:comment "Inverse of hasBusinessProcess: relates a business process to the invoice message it is assigned to." ;
  owl:inverseOf :hasBusinessProcess .

:hasValidationConstraint rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :ValidationConstraint ;
  rdfs:label "has validation constraint" ;
  rdfs:comment "Relates an invoice message to validation constraints." ;
  owl:inverseOf :isValidationConstraintOf .

:isValidationConstraintOf rdf:type owl:ObjectProperty ;
  rdfs:domain :ValidationConstraint ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is validation constraint of" ;
  rdfs:comment "Inverse of hasValidationConstraint: relates a validation constraint to the invoice message it validates." ;
  owl:inverseOf :hasValidationConstraint .

:conformsToEN16931 rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :EN16931Requirement ;
  rdfs:label "conforms to EN 16931" ;
  rdfs:comment "Indicates that the invoice message conforms to a requirement of EN 16931-1." ;
  owl:inverseOf :isEN16931RequirementOf .

:isEN16931RequirementOf rdf:type owl:ObjectProperty ;
  rdfs:domain :EN16931Requirement ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is EN16931 requirement of" ;
  rdfs:comment "Inverse of conformsToEN16931: relates an EN16931 requirement to the invoice message it applies to." ;
  owl:inverseOf :conformsToEN16931 .

:referencesP2PO rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :P2POntologyReference ;
  rdfs:label "references P2P-O" ;
  rdfs:comment "Links the invoice message to a reference in the Purchase-to-Pay Ontology." ;
  owl:inverseOf :isReferencedByInvoiceMessage .

:isReferencedByInvoiceMessage rdf:type owl:ObjectProperty ;
  rdfs:domain :P2POntologyReference ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is referenced by invoice message" ;
  rdfs:comment "Inverse of referencesP2PO: relates a P2P-O reference to the invoice message that references it." ;
  owl:inverseOf :referencesP2PO .

:validatedBySHACL rdf:type owl:ObjectProperty ;
  rdfs:domain :InvoiceMessage ;
  rdfs:range :SHACLConstraint ;
  rdfs:label "validated by SHACL" ;
  rdfs:comment "Indicates that the invoice message is validated by a SHACL constraint." ;
  owl:inverseOf :isSHACLConstraintOf .

:isSHACLConstraintOf rdf:type owl:ObjectProperty ;
  rdfs:domain :SHACLConstraint ;
  rdfs:range :InvoiceMessage ;
  rdfs:label "is SHACL constraint of" ;
  rdfs:comment "Inverse of validatedBySHACL: relates a SHACL constraint to the invoice message it validates." ;
  owl:inverseOf :validatedBySHACL .

#################################################################
# Data Properties
#################################################################
:hasDocumentDate rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain :HeaderSection ;
  rdfs:range xsd:string ;
  rdfs:label "has document date" ;
  rdfs:comment "Date of the invoice document." .

:hasValue rdf:type owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain :SimpleDataElement ;
  rdfs:range xsd:string ;
  rdfs:label "has value" ;
  rdfs:comment "The value of a simple data element." .

#################################################################
# Hierarchies, Disjoint, and DisjointUnion
#################################################################
:InterchangeEnvelope owl:disjointWith :Message .
:Message owl:disjointWith :Segment .
:Segment owl:disjointWith :CompositeDataElement .
:CompositeDataElement owl:disjointWith :SimpleDataElement .
:Organization owl:disjointWith :Item .
:Address owl:disjointWith :Identifier .
:HeaderSection owl:disjointWith :DetailSection .
:HeaderSection owl:disjointWith :SummarySection .
:DetailSection owl:disjointWith :SummarySection .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Complex Axioms & Restrictions
#################################################################
:InvoiceMessage owl:equivalentClass [ rdf:type owl:Class ;
  owl:intersectionOf (
    [ rdf:type owl:Restriction ; owl:onProperty :hasSection ; owl:allValuesFrom :Segment ]
    [ rdf:type owl:Restriction ; owl:onProperty :hasBusinessProcess ; owl:someValuesFrom :BusinessProcess ]
  )
] .

:RoleAssignment owl:equivalentClass [ rdf:type owl:Class ;
  owl:intersectionOf (
    [ rdf:type owl:Restriction ; owl:onProperty :hasRole ; owl:allValuesFrom :AgentRole ]
    [ rdf:type owl:Restriction ; owl:onProperty :inContextOf ; owl:allValuesFrom :InvoiceMessage ]
  )
] .

:LineItem owl:equivalentClass [ rdf:type owl:Class ;
  owl:intersectionOf (
    [ rdf:type owl:Restriction ; owl:onProperty :describesItem ; owl:allValuesFrom :Item ]
    [ rdf:type owl:Restriction ; owl:onProperty :hasNetPrice ; owl:allValuesFrom :Price ]
    [ rdf:type owl:Restriction ; owl:onProperty :hasQuantity ; owl:allValuesFrom :Quantity ]
  )
] .

#################################################################
# Annotations
#################################################################
# All classes and properties have rdfs:label and rdfs:comment as required.

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_Ontology rdf:type owl:Ontology ;
  rdfs:label "EDIFACT INVOIC Ontology" ;
  rdfs:comment "A deeply structured ontology for representing UN/EDIFACT invoice messages, segments, organizations, and business context, aligned with EN 16931-1 and P2P-O standards." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope rdf:type owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "Envelope containing EDIFACT messages." .

:Message rdf:type owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A business message within an interchange envelope." .

:InvoiceMessage rdf:type owl:Class ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An invoice message, such as INVOIC, within the interchange envelope." ;
  rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment rdf:type owl:Class ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." ;
  rdfs:subClassOf :Segment .

:NADSegment rdf:type owl:Class ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." ;
  rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element within a composite data element." .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of an invoice message, containing dates and reference numbers." ;
  rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing individual line items." ;
  rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section providing totals and tax information." ;
  rdfs:subClassOf :Segment .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "An organization involved in the invoice, such as buyer or delivery party." .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in a transaction." .

:RoleAssignment rdf:type owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "A pivot class for reification of organization roles in invoice context." .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address of an organization." .

:Identifier rdf:type owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "An identifier for an organization." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A global location number identifier." ;
  rdfs:subClassOf :Identifier .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price information for items or invoices." .

:Quantity rdf:type owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "Quantity of items sold." .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A line item in the invoice detail section." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary section." .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for document identification." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "Business process assignment for the invoice." .

:ValidationConstraint rdf:type owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "Constraint for validating invoice messages." .

:EN16931Requirement rdf:type owl:Class ;
  rdfs:label "EN 16931 Requirement" ;
  rdfs:comment "A requirement from EN 16931-1 standard." .

:P2POntologyReference rdf:type owl:Class ;
  rdfs:label "P2P-O Reference" ;
  rdfs:comment "Reference to the Purchase-to-Pay Ontology." .

:SHACLConstraint rdf:type owl:Class ;
  rdfs:label "SHACL Constraint" ;
  rdfs:comment "SHACL constraint for automated validation." .

#################################################################
# Object Properties and Inverses
#################################################################
:containsMessage rdf:type owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain :InterchangeEnvelope ;
  rdfs:range :Message ;
  rdfs:label "contains message" ;
  rdfs:comment "Relates an interchange envelope to the messages it contains." ;
  owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope rdf:type owl:ObjectProperty ;
  rdfs:domain :Message ;
