:EDIFACT_INVOIC_Ontology rdf:type owl:Ontology ;
  rdfs:label "EDIFACT INVOIC Ontology" ;
  rdfs:comment "A deeply structured ontology for representing UN/EDIFACT invoice messages, segments, organizations, and business context, aligned with EN 16931-1 and P2P-O standards." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope rdf:type owl:Class ;
  rdfs:label "Interchange Envelope" ;
  rdfs:comment "Envelope containing EDIFACT messages." .

:Message rdf:type owl:Class ;
  rdfs:label "Message" ;
  rdfs:comment "A business message within an interchange envelope." .

:InvoiceMessage rdf:type owl:Class ;
  rdfs:label "Invoice Message" ;
  rdfs:comment "An invoice message, such as INVOIC, within the interchange envelope." ;
  rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
  rdfs:label "Segment" ;
  rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment rdf:type owl:Class ;
  rdfs:label "BGM Segment" ;
  rdfs:comment "Beginning of Message segment for document identification." ;
  rdfs:subClassOf :Segment .

:NADSegment rdf:type owl:Class ;
  rdfs:label "NAD Segment" ;
  rdfs:comment "Name and Address segment for participant details." ;
  rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
  rdfs:label "Composite Data Element" ;
  rdfs:comment "A composite data element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
  rdfs:label "Simple Data Element" ;
  rdfs:comment "A simple data element within a composite data element." .

:HeaderSection rdf:type owl:Class ;
  rdfs:label "Header Section" ;
  rdfs:comment "Header section of an invoice message, containing dates and reference numbers." ;
  rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
  rdfs:label "Detail Section" ;
  rdfs:comment "Detail section listing individual line items." ;
  rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
  rdfs:label "Summary Section" ;
  rdfs:comment "Summary section providing totals and tax information." ;
  rdfs:subClassOf :Segment .

:Organization rdf:type owl:Class ;
  rdfs:label "Organization" ;
  rdfs:comment "An organization involved in the invoice, such as buyer or delivery party." .

:AgentRole rdf:type owl:Class ;
  rdfs:label "Agent Role" ;
  rdfs:comment "A role played by an organization in a transaction." .

:RoleAssignment rdf:type owl:Class ;
  rdfs:label "Role Assignment" ;
  rdfs:comment "A pivot class for reification of organization roles in invoice context." .

:Address rdf:type owl:Class ;
  rdfs:label "Address" ;
  rdfs:comment "Address of an organization." .

:Identifier rdf:type owl:Class ;
  rdfs:label "Identifier" ;
  rdfs:comment "An identifier for an organization." .

:GlobalLocationNumber rdf:type owl:Class ;
  rdfs:label "Global Location Number" ;
  rdfs:comment "A global location number identifier." ;
  rdfs:subClassOf :Identifier .

:Item rdf:type owl:Class ;
  rdfs:label "Item" ;
  rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
  rdfs:label "Price" ;
  rdfs:comment "Price information for items or invoices." .

:Quantity rdf:type owl:Class ;
  rdfs:label "Quantity" ;
  rdfs:comment "Quantity of items sold." .

:LineItem rdf:type owl:Class ;
  rdfs:label "Line Item" ;
  rdfs:comment "A line item in the invoice detail section." .

:Tax rdf:type owl:Class ;
  rdfs:label "Tax" ;
  rdfs:comment "Tax information in the summary section." .

:ReferenceNumber rdf:type owl:Class ;
  rdfs:label "Reference Number" ;
  rdfs:comment "Reference number for document identification." .

:BusinessProcess rdf:type owl:Class ;
  rdfs:label "Business Process" ;
  rdfs:comment "Business process assignment for the invoice." .

:ValidationConstraint rdf:type owl:Class ;
  rdfs:label "Validation Constraint" ;
  rdfs:comment "Constraint for validating invoice messages." .

:EN16931Requirement rdf:type owl:Class ;
  rdfs:label "EN 16931 Requirement" ;
  rdfs:comment "A requirement from EN 16931-1 standard." .

:P2POntologyReference rdf:type owl:Class ;
